namespace ghidra.app.plugin.core.byteviewer;









using docking;
using docking;
using ghidra.app.services;
using ghidra.app.util;
using ghidra.app.util;
using ghidra.framework.plugintool;
using ghidra.program.model.listing;
using ghidra.program.util;
using ghidra.program.util;
using ghidra.util.task;

public class ByteViewerClipboardProvider : ByteCopier, ClipboardContentProviderService {

	private static readonly List<ClipboardType> COPY_TYPES = createCopyTypesList();

	private static List<ClipboardType> createCopyTypesList() {
		List<ClipboardType> copyTypesList = new();
		copyTypesList.add(BYTE_STRING_TYPE);
		copyTypesList.add(BYTE_STRING_NO_SPACE_TYPE);
		copyTypesList.add(PYTHON_BYTE_STRING_TYPE);
		copyTypesList.add(PYTHON_LIST_TYPE);
		copyTypesList.add(CPP_BYTE_ARRAY_TYPE);
		return copyTypesList;
	}

	private bool copyEnabled;
	private bool pasteEnabled;
	private Set<ChangeListener> listeners = new();
	private ProgramByteViewerComponentProvider provider;

	public ByteViewerClipboardProvider(ProgramByteViewerComponentProvider provider,
			PluginTool tool) {
		this.provider = provider;
		this.tool = tool;
	}

	/* @Override */
	public void addChangeListener(ChangeListener listener) {
		listeners.add(listener);
	}

	/* @Override */
	public void removeChangeListener(ChangeListener listener) {
		listeners.remove(listener);
	}

	private void notifyStateChanged() {
		ChangeEvent @event = new ChangeEvent(this);
		foreach (ChangeListener listener in listeners) {
			listener.stateChanged(@event);
		}
	}

	/* @Override */
	public bool paste(Transferable pasteData) {
		try {
			// try the default paste
			return pasteBytes(pasteData);
		}
		catch (Exception e) {
			tool.setStatusInfo("Paste failed: " + e.getMessage(), true);
		}
		return false;
	}

	/* @Override */
	public List<ClipboardType> getCurrentCopyTypes() {
		if (copyEnabled) {
			return COPY_TYPES;
		}
		return EMPTY_LIST;
	}

	/* @Override */
	public Transferable copy(TaskMonitor monitor) {
		string byteString = copyBytesAsString(currentSelection, true, monitor);
		string textSelection = getTextSelection();
		return new ByteStringTransferable(byteString, textSelection);
	}

	protected string getTextSelection() {
		return provider.getCurrentTextSelection();
	}

	/* @Override */
	public Transferable copySpecial(ClipboardType copyType, TaskMonitor monitor) {
		return copyBytes(copyType, monitor);
	}

	private void updateEnablement() {
		copyEnabled = (currentSelection != null && !currentSelection.isEmpty());
		notifyStateChanged();
	}

	void setLocation(ProgramLocation location) {
		currentLocation = location;
	}

	void setSelection(ProgramSelection selection) {
		currentSelection = selection;
		updateEnablement();
	}

	void setProgram(Program p) {
		currentProgram = p;
		currentLocation = null;
		currentSelection = null;
	}

	/* @Override */
	public bool isValidContext(ActionContext context) {
		return context.getComponentProvider() == provider && currentProgram != null;
	}

	/* @Override */
	public ComponentProvider getComponentProvider() {
		return provider;
	}

	/* @Override */
	public bool enableCopy() {
		return true;
	}

	/* @Override */
	public bool enableCopySpecial() {
		return true;
	}

	/* @Override */
	public bool canCopy() {
		return copyEnabled;
	}

	/* @Override */
	public bool canCopySpecial() {
		return copyEnabled;
	}

	/* @Override */
	public bool enablePaste() {
		return true;
	}

	bool isPasteEnabled() {
		return pasteEnabled;
	}

	void setPasteEnabled(bool pasteEnabled) {
		this.pasteEnabled = pasteEnabled;
		notifyStateChanged();
	}

	/* @Override */
	public bool canPaste(DataFlavor[] availableFlavors) {
		if (!pasteEnabled || currentProgram == null) {
			return false;
		}
		if (availableFlavors != null) {
			foreach (DataFlavor flavor in availableFlavors) {
				if (flavor.equals(DataFlavor.stringFlavor)) {
					return true;
				}
			}
		}
		return false;
	}

//==================================================================================================
// Unsupported Operations
//==================================================================================================    

	/* @Override */
	public void lostOwnership(Transferable transferable) {
		// no-op
	}
}
